import { createOfficeWorld } from './world.js';
import { projects,agents } from './data.js';
const $=s=>document.querySelector(s);
const escapeHTML=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let officeWorld=null,running=false,ready=false,controller=null,toastTimer=null;
const activeAgents=new Map(),seenMessages=new Set();
const avatar=a=>`<span class="avatar-window" style="--agent-color:${a.color}" aria-hidden="true">${a.name.slice(0,1)}</span>`;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,3400);}
function renderText(text){return escapeHTML(text).replace(/```(?:[a-zA-Z0-9_-]+)?\n([\s\S]*?)```/g,'<pre><code>$1</code></pre>').replace(/\*\*([^*\n]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`\n]+)`/g,'<code>$1</code>');}
$('#agent-grid').innerHTML=agents.map(a=>`<button class="agent-card${a.id==='nova'?' is-leader':''}" style="--agent-color:${a.color}" data-agent="${a.id}" aria-label="Conosci ${a.name}, ${a.role}"><div class="agent-card-head">${avatar(a)}<div><h3>${a.name}${a.id==='nova'?'<span class="leader-badge">Leader</span>':''}</h3><p class="agent-role">${a.role}</p></div></div><p class="agent-task">${a.task}</p><div class="agent-foot"><span class="agent-state">Disponibile</span><span class="agent-link" aria-hidden="true">↗</span></div></button>`).join('');
agents.forEach(a=>{const button=document.createElement('button');button.className='office-agent';button.dataset.agent=a.id;button.setAttribute('aria-label',`Conosci ${a.name}, ${a.role}`);button.style.setProperty('--agent-color',a.color);button.innerHTML=`<span class="agent-nameplate"><span class="person-dot"></span>${a.name}${a.id==='nova'?'<span class="leader-badge">Leader</span>':''}<span class="person-plus">＋</span></span>`;$('#office-world').append(button);});
const portfolio=document.createElement('section');portfolio.className='portfolio-section';portfolio.setAttribute('aria-labelledby','portfolio-title');portfolio.innerHTML=`<div class="section-title"><h2 id="portfolio-title">I tuoi progetti <span>08</span></h2><p>Puoi parlarne direttamente in chat.</p></div><div class="portfolio-grid">${projects.slice(1).map((p,i)=>`<button class="project-card" data-project="${p.id}"><span class="project-index">${String(i+1).padStart(2,'0')}</span><span class="project-category">${p.category}</span><h3>${p.name}</h3><p>${p.description}</p><span class="project-action">Parliamone <span aria-hidden="true">↗</span></span></button>`).join('')}</div><p class="portfolio-note">Il team conosce le descrizioni che hai condiviso. Cartelle e repository non sono ancora collegati.</p>`;document.querySelector('footer').before(portfolio);
function focusChat(text){if(typeof text==='string')$('#chat-input').value=text;$('#chat-input').scrollIntoView({behavior:'smooth',block:'center'});$('#chat-input').focus({preventScroll:true});}
$('#new-mission').addEventListener('click',()=>focusChat());
document.querySelectorAll('[data-chat-prompt]').forEach(button=>button.addEventListener('click',()=>focusChat(button.dataset.chatPrompt)));
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const p=projects.find(p=>p.id===button.dataset.project);focusChat(`Parliamo di ${p.name}: `);}));
function openDialog(eyebrow,content){$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=content;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function showAgent(id){const a=agents.find(a=>a.id===id);if(!a)return;openDialog('IL TUO TEAM · COLLEGA AI',`<div class="dialog-agent-header">${avatar(a)}<div><h2 id="dialog-title" class="dialog-title" style="color:${a.color}">${a.name}</h2><p class="muted">${a.role}</p></div></div><p class="agent-quote">“${a.quote}”</p><p class="dialog-description">${a.description}</p><div class="dialog-section"><h3>Cosa porta al team</h3><ul>${a.skills.map(s=>`<li>${s}</li>`).join('')}</ul></div><p class="dialog-note">Risponde tramite Codex. In questa versione può ragionare, scrivere e aiutarti a pianificare; non ha ancora accesso ai tuoi repository o alla ricerca web.</p><div class="dialog-actions"><button class="button primary" id="talk-to-agent">Parla con ${a.name} ↗</button></div>`);$('#talk-to-agent').addEventListener('click',()=>{$('#detail-dialog').close();focusChat(`@${a.name} `);});}
document.querySelectorAll('[data-agent]').forEach(b=>b.addEventListener('click',()=>showAgent(b.dataset.agent)));
$('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target!==$('#detail-dialog'))return;const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();});
function updateAgent(id,status,task){const agent=agents.find(a=>a.id===id);if(!agent)return;const card=$(`.agent-card[data-agent="${id}"]`),badge=$(`.office-agent[data-agent="${id}"]`);const active=status==='Al lavoro';officeWorld?.setAgentStatus(id,status);card.classList.toggle('busy',active);badge.classList.toggle('busy',active);card.querySelector('.agent-state').textContent=status;card.querySelector('.agent-task').textContent=task||agent.task;if(active)activeAgents.set(id,agent.name);else activeAgents.delete(id);const names=[...activeAgents.values()];$('#chat-thinking').hidden=names.length===0;$('#chat-thinking').textContent=names.length?names.join(', ')+(names.length===1?' sta pensando…':' stanno collaborando…'):'';$('#team-status').textContent=names.length?`${names.length} ${names.length===1?'collega al lavoro':'colleghi al lavoro'}`:'5 colleghi pronti';if(names.length)$('#office-message').textContent=names.length===1?`${names[0]} sta preparando una risposta.`:`${names.join(' e ')} si dividono il lavoro.`;}
function addMessage(message){if(seenMessages.has(message.id))return;seenMessages.add(message.id);const agent=agents.find(a=>a.id===message.agentId);const element=document.createElement('article');element.className='chat-message '+(message.role==='user'?'from-user':'from-team');element.dataset.messageId=message.id;const stamp=new Date(message.createdAt).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});element.innerHTML=`<div class="chat-message-head"><span class="chat-person" style="--person-color:${agent?.color||'#4e6843'}">${message.role==='user'?'Tu':escapeHTML(agent?.name||'Studio')}</span><time>${stamp}</time></div><div class="chat-message-body">${renderText(message.text)}</div>`;$('#chat-messages').append(element);$('#chat-messages').scrollTop=$('#chat-messages').scrollHeight;$('#chat-starters')?.remove();$('.chat-starters').hidden=seenMessages.size>1;}
function updateContext(id){const p=projects.find(p=>p.id===id);$('#chat-context').textContent=!p||id==='portfolio'?'Lo riconosciamo dalla conversazione':p.name;document.querySelectorAll('.project-card').forEach(b=>b.classList.toggle('selected-project',b.dataset.project===id));}
function setRunning(value){running=value;$('#chat-send').hidden=value;$('#chat-send').disabled=!ready;$('#chat-stop').hidden=!value;$('#new-chat').disabled=value;$('#chat-input').disabled=value;document.querySelectorAll('.chat-starters button').forEach(b=>b.disabled=value);if(!value){for(const a of agents)if(activeAgents.has(a.id))updateAgent(a.id,'Disponibile',a.task);$('#office-message').textContent='La conversazione continua. Le idee anche.';}}
async function loadStudio(){try{const res=await fetch('/api/studio');if(!res.ok)throw Error('Non riesco a collegarmi allo studio locale.');const data=await res.json();ready=!!data.provider.ready;$('#provider-badge').textContent=ready?'Codex collegato':'Codex da collegare';$('#provider-note').textContent=ready?'Codex · '+data.provider.auth:(data.provider.reason||'Codex non disponibile');$('#chat-send').disabled=!ready;$('#chat-messages').replaceChildren();seenMessages.clear();data.messages.forEach(addMessage);updateContext(data.projectId);if(!ready){$('#chat-error').hidden=false;$('#chat-error').textContent=data.provider.reason;}}catch(error){$('#provider-badge').textContent='Connessione non disponibile';$('#provider-note').textContent='Avvia l’app con npm start';$('#chat-error').hidden=false;$('#chat-error').textContent=error.message;}}
function handleEvent(event){if(event.type==='message')addMessage(event.message);else if(event.type==='status')updateAgent(event.agentId,event.status,event.task);else if(event.type==='context')updateContext(event.projectId);else if(event.type==='error'){$('#chat-error').hidden=false;$('#chat-error').textContent=event.message;}else if(event.type==='done')updateContext(event.projectId);}
async function sendMessage(event){event?.preventDefault();if(running||!ready)return;const text=$('#chat-input').value.trim();if(!text){$('#chat-input').focus();return;}$('#chat-error').hidden=true;setRunning(true);controller=new AbortController();try{const res=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:JSON.stringify({message:text}),signal:controller.signal});if(!res.ok){const failure=await res.json();throw Error(failure.error||'Invio non riuscito.');}$('#chat-input').value='';const reader=res.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);for(const line of frame.split('\n'))if(line.startsWith('data: ')){handleEvent(JSON.parse(line.slice(6)));}}}}catch(error){if(error.name==='AbortError')toast('Richiesta interrotta. I messaggi ricevuti restano salvati.');else{$('#chat-error').hidden=false;$('#chat-error').textContent=error.message;}}finally{setRunning(false);controller=null;}}
$('#chat-form').addEventListener('submit',sendMessage);$('#chat-input').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendMessage();}});$('#chat-stop').addEventListener('click',()=>controller?.abort());
$('#new-chat').addEventListener('click',async()=>{if(running)return;try{const res=await fetch('/api/conversation/new',{method:'POST',headers:{'Content-Type':'application/json','X-Fuori-Studio':'local'},body:'{}'});if(!res.ok){const data=await res.json();throw Error(data.error);}await loadStudio();toast('Nuova conversazione. La precedente è conservata sul Mac.');}catch(error){toast(error.message);}});
$('#focus-toggle').addEventListener('click',()=>{const enabled=document.body.classList.toggle('focus-mode');$('#focus-toggle').setAttribute('aria-pressed',String(enabled));officeWorld?.setQuiet(enabled);toast(enabled?'Quiet mode: movimenti in pausa.':'Il team torna in movimento.');});
const landscapes={anthill:{title:'Lo studio nel formicaio',label:'FORMICAIO · STUDIO 01',description:'Ufficio 3D al centro di un grande formicaio, con sentieri e formiche laboriose attorno ai lavoratori.'},forest:{title:'Lo studio nel bosco',label:'BOSCO · STUDIO 02',description:'Ufficio 3D a blocchi tra alberi, sentieri e ruscello.'},beach:{title:'Lo studio sulla spiaggia',label:'SPIAGGIA · STUDIO 03',description:'Ufficio 3D a blocchi tra palme, sabbia e mare turchese.'},mountain:{title:'Lo studio in montagna',label:'MONTAGNA · STUDIO 04',description:'Ufficio 3D a blocchi tra pini, prati e cime innevate.'}};
function setLandscape(name){const scene=landscapes[name];document.body.dataset.landscape=name;$('#office-illustration').setAttribute('aria-label',scene.description);$('#office-title').textContent=scene.title;$('#landscape-label').textContent=scene.label;document.querySelectorAll('.landscape-button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.landscape===name)));officeWorld?.setLandscape(name);}
document.querySelectorAll('.landscape-button').forEach(b=>b.addEventListener('click',()=>setLandscape(b.dataset.landscape)));$('#reset-camera').addEventListener('click',()=>officeWorld?.resetCamera());
$('#zoom-in').addEventListener('click',()=>officeWorld?.zoomBy(1.2));$('#zoom-out').addEventListener('click',()=>officeWorld?.zoomBy(1/1.2));$('#world-overview').addEventListener('click',()=>officeWorld?.showOverview());
try{officeWorld=createOfficeWorld($('#office-illustration'),{onSelect:showAgent,onCameraChange:({overview,zoom})=>{$('#world-overview').setAttribute('aria-pressed',String(overview));$('#office-world').classList.toggle('distant-view',zoom<.68);},onPositions:positions=>{for(const p of positions){const badge=$(`.office-agent[data-agent="${p.id}"]`);if(badge){badge.hidden=!p.visible;badge.style.left=p.x+'px';badge.style.top=p.y+'px';}}}});const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');if(reduced.matches){document.body.classList.add('focus-mode');$('#focus-toggle').setAttribute('aria-pressed','true');officeWorld.setQuiet(true);}reduced.addEventListener('change',event=>{document.body.classList.toggle('focus-mode',event.matches);$('#focus-toggle').setAttribute('aria-pressed',String(event.matches));officeWorld?.setQuiet(event.matches);});setLandscape('anthill');}catch(error){$('#office-illustration').innerHTML='<div class="graphics-error"><strong>Il mondo 3D non è riuscito ad aprirsi.</strong><p>Riapri questa pagina in un browser con WebGL attivo. La chat resta utilizzabile.</p></div>';document.querySelectorAll('.office-agent').forEach(b=>b.hidden=true);document.querySelectorAll('.camera-controls button').forEach(b=>b.disabled=true);console.error('Avvio del mondo 3D non riuscito:',error);}
loadStudio();
